entries[334743] = { ["name"] = "Dunkler Vortrag", ["text"] = "Unbegrenzte Reichweite\nSofort\nLord Stavros weist Spielercharaktere einander für einen Paartanz zu, der 8 Sek. lang anhält. Solange Ihr mehr als 8 Meter von Eurem Partner entfernt seid, bestraft Lord Stavros Euch und fügt Euch alle 0.5 Sek. 4445 Schattenschaden zu.\n\nZusätzlich regt Lord Stavros Tanzschritte an, indem er die Positionen aller Partner alle 0.5 Sek. markiert, sodass sie ausbrechen und allen Spielercharakteren innerhalb von 2.5 Metern 23702 Schattenschaden zufügen." }
entries[334744] = { ["name"] = "Bwonsamdi" }
entries[334745] = { ["name"] = "Das Auge des Kerkermeisters", ["text"] = "Sofort\nIm Schlund Quests abzuschließen, Schätze zu öffnen oder seltene Gegner zu töten, zieht jetzt das Auge des Kerkermeisters auf Euch. Dieser wird Euch mit zunehmend tödlicheren Strafen quälen." }
entries[334746] = { ["name"] = "Zugang zu Torghast", ["text"] = "Sofort\nSchaltet Zugang zu Torghast, dem Turm der Verdammten, frei." }
entries[334747] = { ["name"] = "Fleisch werfen", ["text"] = "20 Meter Reichweite\nWirken in 2.5 sek.\nFügt dem gegnerischen Ziel 3636674 körperlichen Schaden zu." }
entries[334748] = { ["name"] = "Flüssigkeiten entziehen", ["text"] = "100 Meter Reichweite\nWirken in 2 sek.\nDer Zaubernde entzieht dem Ziel Flüssigkeiten und fügt ihm 4 Sek. lang alle 1 Sek. 1697115 Seuchenschaden zu." }
entries[334749] = { ["name"] = "Flüssigkeiten entziehen", ["text"] = "100 Meter Reichweite\nSofort\nDer Zaubernde entzieht dem Ziel Flüssigkeiten und fügt ihm 4 Sek. lang alle 1 Sek. 1697115 Seuchenschaden zu." }
entries[334750] = { ["name"] = "Abschuss", ["text"] = "40 Meter Reichweite\nSofort 1.5 sek. Abklingzeit\nSchleudert Euch hoch in die Luft und lässt Euch dann für kurze Zeit gleiten." }
