entries[334753] = { ["name"] = "Vereinte Front", ["text"] = "Sofort\nDer Zaubernde wird von Verbündeten in der Nähe verstärkt. Sein Schaden ist für jeden blutroten Kadetten innerhalb von 10 Metern um 20% erhöht." }
entries[334755] = { ["name"] = "Essenzentzug", ["text"] = "Sofort\nErhöht den durch ' Gefräßiges Miasma ' erlittenen Schaden 20 Sek. lang um 8%.\n\nDieser Effekt ist stapelbar." }
