entries[334757] = { ["name"] = "Schemen von Bargast", ["text"] = "Wirken in 2 sek.\nBargast erschafft Schemen von sich, die ' Tödliches Brüllen ' einsetzen.\n\nWährend sie von einem Kontrollverlusteffekt betroffen sind, erhalten Schemen von Bargast Stapel von ' Destabilisieren ', die sämtlichen erlittenen Schaden um 100% erhöhen." }
